import { StyleFn } from "..";

// minimalistic css reset that will benefit every one
// don't set any style here that could conflict with custom app styles
export const Baseline: StyleFn = (theme, mode) => {
  const { color, font } = theme;
  const textStyles = Text(theme, mode);
  return {
    "@global": {
      html: {
        boxSizing: "border-box",
      },
      "*, *::before, *::after": {
        boxSizing: "border-box",
      },
      body: {
        fontFamily: font.family.default,
        fontSize: font.size.medium,
        lineHeight: font.lineheight.medium,
        "@media print": {
          backgroundColor: color.palette.base.white,
        },
      },
      // optin global styles
      ".ds-styles": {
        color: color.text.neutral.default[mode],
        backgroundColor: color.surface.interaction.default[mode],
        "& h1": textStyles._h1,
        "& h2": textStyles._h2,
        "& h3": textStyles._h3,
        "& h4": textStyles._h4,
        "& h5": textStyles._h5,
        "& h6": textStyles._h6,
      },
    },
  };
};

export const Text: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;

  const heading = {
    fontFamily: font.family.default,
    fontWeight: font.weight.bold,
    color: color.text.accent.default[mode],
    marginTop: 0,
    marginBottom: size.spacing[8],
  };
  const subHeading = {
    fontWeight: font.weight.light,
  };
  const primaryColor = {
    color: color.text.neutral.default[mode],
  };
  const styles: any = {
    root: primaryColor,
    _body: primaryColor,
    _heading: {
      color: color.text.accent.default[mode],
    },
    _label: {
      color: color.text.neutral.strong[mode],
    },
    _legend: {
      color: color.text.neutral.default[mode],
    },
    _h1: {
      ...heading,
      fontSize: font.size["heading-1"],
      lineHeight: font.lineheight["heading-1"],
    },
    _h2: {
      ...heading,
      fontSize: font.size["heading-2"],
      lineHeight: font.lineheight["heading-2"],
    },
    _h3: {
      ...heading,
      fontSize: font.size["heading-3"],
      lineHeight: font.lineheight["heading-3"],
    },
    _h4: {
      ...heading,
      fontSize: font.size["heading-4"],
      lineHeight: font.lineheight["heading-4"],
      fontWeight: font.weight.medium,
    },
    _h5: {
      ...heading,
      fontSize: font.size["heading-5"],
      lineHeight: font.lineheight["heading-5"],
      fontWeight: font.weight.medium,
    },
    _h6: {
      ...heading,
      fontSize: font.size["heading-6"],
      lineHeight: font.lineheight["heading-6"],
      fontWeight: font.weight.medium,
    },
    _subH1: {
      extend: ["_h1"],
      ...subHeading,
    },
    _subH2: {
      extend: ["_h2"],
      ...subHeading,
    },
    _subH3: {
      extend: ["_h3"],
      ...subHeading,
    },
    _subH4: {
      extend: ["_h4"],
      ...subHeading,
    },
    _subH5: {
      extend: ["_h5"],
      ...subHeading,
    },
    _subH6: {
      extend: ["_h6"],
      ...subHeading,
    },
    _noGutter: {
      marginBottom: 0,
    },
    _mono: {
      fontFamily: font.family.mono,
      ...primaryColor,
    },
  };
  ["xsmall", "small", "medium", "large"].forEach(
    (size: "xsmall" | "small" | "medium" | "large") => {
      styles[`_${size}`] = {
        fontSize: font.size[size],
        lineHeight:
          size === "large"
            ? font.lineheight["heading-6"]
            : font.lineheight[size],
      };
    }
  );
  // monospace variants
  return styles;
};

/** Utilities for Screenreaders */
export const SROnly: StyleFn = () => {
  return {
    // FIXME could be replaced with https://polished.js.org/docs/#hidevisually
    root: {
      position: "absolute",
      width: 1,
      height: 1,
      margin: -1,
      overflow: "hidden",
      clip: "rect(0,0,0,0)",
    },
    _focusable: {
      position: "static",
      width: "auto",
      height: "auto",
      margin: 0,
      overflow: "visible",
      clip: "auto",
    },
  };
};
